import { z } from 'zod';
import { breedIdSchema } from './breed-names.ts';

/**
 * Schema of src/lib/data/images.json (generated by scripts/fetch-credits.ts from the Wikimedia
 * Commons API). One photo per breed at most, only under a free licence, always with its credit.
 */

/** Licences accepted on Dogtrails (docs/PLAN.md: CC BY / BY-SA, attribution per file). */
export const imageLicenceKindSchema = z.enum(['cc0', 'pd', 'cc-by', 'cc-by-sa']);

/** The Commons API serves scaled thumbnails from thumb.wikimedia.org and unscaled files from upload.wikimedia.org. */
export const WIKIMEDIA_FILE_HOSTS = ['upload.wikimedia.org', 'thumb.wikimedia.org'];

const httpsUrl = z.url({ protocol: /^https$/ });

export const imageSchema = z
	.strictObject({
		breedId: breedIdSchema,
		/** Commons file name without the `File:` prefix. */
		file: z.string().min(1),
		/** Who picked the file: the Wikidata P18 of breeds.json, or the hand-picked table. */
		chosenBy: z.enum(['wikidata-p18', 'data/manual/photos.json']),
		/** The file description page on Commons. */
		filePage: z.url().refine((u) => new URL(u).hostname === 'commons.wikimedia.org', 'not a Commons page'),
		/** Plain text (HTML stripped) from extmetadata `Attribution`, else `Artist`. */
		author: z.string().min(1),
		/** Where the credit text comes from: the Commons metadata, or the hand-checked table. */
		authorFrom: z.enum(['commons-extmetadata', 'data/manual/photos.json']),
		licence: z.strictObject({
			kind: imageLicenceKindSchema,
			/** extmetadata `LicenseShortName`, e.g. `CC BY-SA 4.0`. */
			name: z.string().min(1),
			/** extmetadata `LicenseUrl`; Commons gives none for public-domain files. */
			url: z.url().nullable()
		}),
		/** Self-hosted thumbnail; width/height are the box it is drawn in (never above the original). */
		thumb: z.strictObject({
			/** Path under static/, served by the site. */
			path: z.string().regex(/^photos\/[a-z0-9-]+\.(jpg|png|webp|gif)$/),
			/** Where it was downloaded from, without tracking parameters. */
			sourceUrl: httpsUrl.refine((u) => WIKIMEDIA_FILE_HOSTS.includes(new URL(u).hostname), 'not a Wikimedia file host'),
			width: z.int().positive(),
			height: z.int().positive()
		}),
		original: z.strictObject({ width: z.int().positive(), height: z.int().positive() }),
		/** ISO date the metadata was read from the API. */
		retrieved: z.iso.date()
	})
	.refine((i) => i.licence.url !== null || i.licence.kind === 'pd', {
		message: 'only a public-domain file may have no licence url',
		path: ['licence', 'url']
	});

export const imagesFileSchema = z
	.strictObject({
		source: z.strictObject({
			description: z.string().min(1),
			api: z.url(),
			inputs: z.array(z.string().min(1)).min(1),
			notes: z.array(z.string())
		}),
		generatedBy: z.string().min(1),
		generatedAt: z.iso.datetime(),
		images: z.array(imageSchema)
	})
	.superRefine((f, ctx) => {
		const seen = new Set<string>();
		f.images.forEach((im, i) => {
			if (seen.has(im.breedId)) ctx.addIssue({ code: 'custom', path: ['images', i, 'breedId'], message: `two images for ${im.breedId}` });
			seen.add(im.breedId);
		});
	});

export type ImageLicenceKind = z.infer<typeof imageLicenceKindSchema>;
export type BreedImage = z.infer<typeof imageSchema>;
export type ImagesFile = z.infer<typeof imagesFileSchema>;
